# ============================================================
# V48 · Persistência entre páginas, envio e validação documental
# Os dados preenchidos ficam em rascunho até o envio explícito do eixo.
# Nenhum item não avaliado pode ser convertido automaticamente em código 0.
# ============================================================
if "scores" not in st.session_state:
    st.session_state.scores = {}
if "axis_submissions" not in st.session_state:
    st.session_state.axis_submissions = {}
if "draft_records" not in st.session_state:
    st.session_state.draft_records = {}

AXIS_SEQUENCE = ("Contábil", "Financeiro", "Estratégico")
SUBMISSION_SEQUENCE = ("Identificação", *AXIS_SEQUENCE, "Integração")
AXIS_PAGES = {
    "Contábil": "02 · Eixo Contábil",
    "Financeiro": "03 · Eixo Financeiro",
    "Estratégico": "04 · Eixo Estratégico",
}
EXTRA_PAGES = {"Identificação": "01B · Identificação do fenômeno", "Integração": "04B · Integração dos eixos"}
GROUP_PAGES = {**EXTRA_PAGES, **AXIS_PAGES}
NAV_PAGES = ["APRESENTAÇÃO", "01 · Visão geral", EXTRA_PAGES["Identificação"],
             *AXIS_PAGES.values(), EXTRA_PAGES["Integração"], "05 · Diagnóstico"]
STATUS_UNASSESSED = "Não avaliado"
STATUS_NEGATIVE = "Não localizado no corpus (0)"
STATUS_POSITIVE = "Evidência localizada (1)"
STATUS_OPTIONS = [STATUS_UNASSESSED, STATUS_NEGATIVE, STATUS_POSITIVE]


def axis_items(axis):
    return ALL_ITEMS.get(axis, [])


def response_key(axis, item):
    return re.sub(r"[^a-z0-9]+", "_", norm(axis + "_" + item)).strip("_")


def _case_identity():
    """Identificação canônica: NÃO depende de campos que o Streamlit pode apagar."""
    values = st.session_state.get("case_identity")
    if not isinstance(values, dict):
        values = {
            "company": str(st.session_state.get("audit_company", "") or "").strip(),
            "year": str(st.session_state.get("audit_year", "Selecione")),
            "issuer": str(st.session_state.get("audit_issuer", "") or "").strip(),
            "standard": str(st.session_state.get("audit_standard", "Não informado")),
        }
        st.session_state.case_identity = values
    return (
        str(values.get("company", "") or "").strip(),
        str(values.get("year", "Selecione")),
        str(values.get("issuer", "") or "").strip(),
        str(values.get("standard", "Não informado")),
    )


def _context_ready():
    company, year, issuer, _ = _case_identity()
    return bool(company and year not in ("Selecione", "", "None") and issuer)


def reset_case_assessment():
    """Limpa exclusivamente respostas documentais; não altera a unidade de análise."""
    for key in list(st.session_state.keys()):
        if key.startswith(("status_", "document_", "page_ref_", "quote_", "reason_", "scope_")):
            del st.session_state[key]
    st.session_state.axis_submissions = {}
    st.session_state.draft_records = {}


IDENTITY_FIELDS = ("company", "year", "issuer", "standard")
IDENTITY_DEFAULTS = {"company": "", "year": "Selecione", "issuer": "", "standard": "Não informado"}


def _identity_complete(identity):
    """A unidade deve ter empresa, exercício selecionado e emissora/escopo."""
    return bool(identity[0] and identity[1] != "Selecione" and identity[2])


def _handle_identity_change(origin="main"):
    """Copia os campos de UI para um dicionário persistente e independente dos widgets.

    A identidade pode desaparecer do DOM ao acessar o diagnóstico, mas os valores
    salvos em `case_identity` permanecem na sessão. A mudança de empresa/ano/escopo
    bloqueia a reutilização de evidências da empresa anterior.
    """
    previous = _case_identity()
    updated = dict(st.session_state.get("case_identity", {}))
    for field in IDENTITY_FIELDS:
        key = "main_audit_" + field
        if key in st.session_state:
            updated[field] = str(st.session_state[key]).strip()
    current = (
        updated.get("company", ""), updated.get("year", "Selecione"),
        updated.get("issuer", ""), updated.get("standard", "Não informado")
    )
    if _identity_complete(previous) and previous[:3] != current[:3]:
        reset_case_assessment()
    st.session_state.case_identity = updated
    # Compatibilidade com a exportação CSV já utilizada na versão anterior.
    for field in IDENTITY_FIELDS:
        st.session_state["audit_" + field] = updated.get(field, IDENTITY_DEFAULTS[field])
    st.session_state["_previous_case_identity"] = current


def _render_case_identity_editor():
    """Editor único da identidade, dentro dos eixos, nunca na barra lateral."""
    with st.container(border=True):
        st.markdown("#### Unidade de análise")
        st.caption("A identificação permanece salva enquanto você percorre os três eixos.")
        identity = st.session_state.get("case_identity", {})
        for field in IDENTITY_FIELDS:
            value = identity.get(field, IDENTITY_DEFAULTS[field])
            if field == "year":
                # Selectbox usa INTEIROS; identidade canônica usa string.
                # Evita que "2022" seja confundido com a opção 2022.
                try:
                    value = int(value)
                    if value not in range(2021, 2036):
                        value = "Selecione"
                except (ValueError, TypeError):
                    value = "Selecione"
            key = "main_audit_" + field
            if key not in st.session_state:
                st.session_state[key] = value
        c1, c2 = st.columns([2, 1])
        with c1:
            st.text_input("Empresa analisada", key="main_audit_company",
                          placeholder="Ex.: XP Inc.", on_change=_handle_identity_change)
        with c2:
            st.selectbox("Exercício", ["Selecione", *range(2021, 2036)],
                         key="main_audit_year", on_change=_handle_identity_change)
        st.text_input("Pessoa jurídica emissora / nível de consolidação", key="main_audit_issuer",
                      placeholder="Ex.: XP Inc. and subsidiaries · consolidado",
                      on_change=_handle_identity_change)
        st.selectbox("Padrão declarado no documento",
                     ["Não informado", "IFRS (IASB)", "CPC / IFRS", "US GAAP", "Outro"],
                     key="main_audit_standard", on_change=_handle_identity_change)
        if _context_ready():
            st.success("Unidade de análise identificada. Os três eixos compartilharão este contexto.")
        else:
            st.warning("Identifique empresa, exercício e emissora/escopo acima antes de enviar o eixo.")


def _brief_element_definition(item):
    """Primeira frase do dicionário operacional completo de 48 variáveis."""
    definition = str(EVIDENCE_RULES.get(item, {}).get("definition") or "").strip()
    if not definition:
        definition = str(EVIDENCE_RULES.get(item, {}).get("criterion") or "").strip()
    first_sentence = re.split(r"(?<=\.)\s+", definition, maxsplit=1)[0]
    if len(first_sentence) > 280:
        first_sentence = first_sentence[:277].rsplit(" ", 1)[0].rstrip(".,; ") + "…"
    return first_sentence


def evidence_record(axis, item):
    """Consulta widgets ativos ou o rascunho persistente entre páginas.

    Streamlit elimina chaves de widgets que deixam de ser renderizados; a
    avaliação nunca deve depender exclusivamente dessas chaves temporárias.
    """
    token = response_key(axis, item)
    stored = st.session_state.draft_records.get(axis, {}).get(item, {})
    def field(prefix, name, default=""):
        key = prefix + token
        if key in st.session_state:
            return str(st.session_state[key] or "")
        return str(stored.get(name, default) or "")
    return {
        "status": st.session_state.get("status_" + token,
                                       stored.get("status", STATUS_UNASSESSED)),
        "document": field("document_", "document"),
        "page": field("page_ref_", "page"),
        "quote": field("quote_", "quote"),
        "link_reason": field("reason_", "link_reason"),
        "scope": field("scope_", "scope"),
    }


def _commit_item(axis, item):
    """Transfere SOMENTE o item editado para a cópia persistente da sessão."""
    token = response_key(axis, item)
    previous = st.session_state.draft_records.get(axis, {}).get(item, {})
    record = dict(previous)
    mapping = (("status_", "status"), ("document_", "document"),
               ("page_ref_", "page"), ("quote_", "quote"),
               ("scope_", "scope"), ("reason_", "link_reason"))
    for prefix, field in mapping:
        key = prefix + token
        if key in st.session_state:
            record[field] = st.session_state[key]
    record.setdefault("status", STATUS_UNASSESSED)
    changed_status = record["status"] != previous.get("status", STATUS_UNASSESSED)
    if changed_status:
        for field in ("page", "quote", "link_reason", "scope"):
            record[field] = ""
            widget_key = {"page":"page_ref_", "quote":"quote_",
                          "link_reason":"reason_", "scope":"scope_"}[field] + token
            if widget_key in st.session_state:
                st.session_state[widget_key] = ""
    record = _canonical_record(record)
    st.session_state.draft_records.setdefault(axis, {})[item] = record
    return record


def _sync_axis_draft(axis):
    """Sincroniza os elementos visíveis; nunca lê outro eixo nem destrói envios anteriores."""
    for item in axis_items(axis):
        _commit_item(axis, item)


def _hydrate_axis_widgets(axis):
    """Preenche os widgets efêmeros a partir do armazenamento persistente."""
    mapping = (("status_", "status"), ("document_", "document"),
               ("page_ref_", "page"), ("quote_", "quote"),
               ("scope_", "scope"), ("reason_", "link_reason"))
    for item in axis_items(axis):
        token = response_key(axis, item)
        record = st.session_state.draft_records.get(axis, {}).get(item, {})
        for prefix, field in mapping:
            key = prefix + token
            if key not in st.session_state and field in record:
                st.session_state[key] = record[field]


def mark_axis_dirty(axis, item):
    """Callback de edição: salva a linha e invalida apenas o envio desse eixo."""
    _commit_item(axis, item)
    st.session_state.axis_submissions.pop(axis, None)


def _canonical_record(record):
    """Ignora valores antigos dos campos ocultos ao alternar código 1/0.

    O Streamlit pode descartar o estado de widgets temporariamente invisíveis
    após cada rerun. Apenas os campos relevantes ao status formam o envio.
    """
    base = {"status": record.get("status", STATUS_UNASSESSED),
            "document": str(record.get("document") or ""),
            "page": "", "quote": "", "link_reason": "", "scope": ""}
    if base["status"] == STATUS_POSITIVE:
        base["page"] = str(record.get("page") or "")
        base["quote"] = str(record.get("quote") or "")
        base["link_reason"] = str(record.get("link_reason") or "")
    elif base["status"] == STATUS_NEGATIVE:
        base["scope"] = str(record.get("scope") or "")
    return base


def _is_ui_error_text(value):
    """Avisos mostrados na página não são evidências corporativas."""
    text = norm(value)
    return ("registros positivos permanecem pendentes" in text
            or "registro pendente: informe" in text
            or "nao foram pontuados" in text
            or "preencha a empresa, o exercicio" in text)


def _record_classification(record, context_ok=True, require_link=False):
    """Retorna situação inequívoca, sem inferir ausência a partir de não resposta.

    Esta função é intencionalmente independente do Streamlit para testes.
    """
    status = record.get("status", STATUS_UNASSESSED)
    if status == STATUS_UNASSESSED:
        return "unanswered", "Selecione 1 ou 0 e documente a decisão."
    if status not in (STATUS_POSITIVE, STATUS_NEGATIVE):
        return "pending", "Situação de codificação inválida."
    if not context_ok:
        return "pending", "Complete empresa, exercício e emissora/escopo no início do eixo."

    doc = str(record.get("document") or "").strip()
    if len(doc) < 5 or _is_ui_error_text(doc):
        return "pending", "Informe o nome real do relatório/documento examinado."
    if status == STATUS_NEGATIVE:
        # Código 0 significa ausência no documento examinado. A identificação
        # do relatório é suficiente para a validação funcional; não se exige
        # campo adicional de delimitação da busca. O documento deve ser real.
        return "no", ""

    page = str(record.get("page") or "").strip()
    quote = str(record.get("quote") or "").strip()
    if len(page) < 2 or _is_ui_error_text(page):
        return "pending", "Para código 1, indique página, nota ou localização verificável."
    if len(quote) < 12 or _is_ui_error_text(quote):
        return "pending", "Para código 1, transcreva o trecho original que fundamenta a decisão."
    if require_link:
        reason = str(record.get("link_reason") or "").strip()
        if len(reason) < 12 or _is_ui_error_text(reason):
            return "pending", "Explique a ligação explicitamente descrita no documento."
    return "yes", ""


def evidence_valid(axis, item, require_link=False):
    return _record_classification(evidence_record(axis, item), _context_ready(), require_link)[0] == "yes"


def negative_valid(axis, item):
    return _record_classification(evidence_record(axis, item), _context_ready())[0] == "no"


def _draft_breakdown(axis):
    counts = {"yes": 0, "no": 0, "pending": 0, "unanswered": 0}
    for item in axis_items(axis):
        status, _ = _record_classification(evidence_record(axis, item), _context_ready(), require_link=(axis == "Integração"))
        counts[status] += 1
    assert sum(counts.values()) == len(axis_items(axis))
    return counts


def _submission_for(axis):
    """Confere o envio com a cópia canônica, nunca com widgets apagáveis.

    Os valores da página corrente são sincronizados pelos callbacks. Assim,
    navegar para outro eixo ou abrir o diagnóstico não invalida dados enviados.
    """
    entry = st.session_state.axis_submissions.get(axis)
    if not entry or entry.get("context") != _case_identity():
        return None
    current = {
        item: _canonical_record(st.session_state.draft_records.get(axis, {}).get(item, {}))
        for item in axis_items(axis)
    }
    if entry.get("items") != current:
        return None
    if any(_record_classification(rec, True, require_link=(axis == "Integração"))[0] not in ("yes", "no")
           for rec in current.values()):
        return None
    return entry


def _submitted_breakdown(axis):
    entry = _submission_for(axis)
    if entry is None:
        return None
    counts = {"yes": 0, "no": 0, "pending": 0, "unanswered": 0}
    for item in axis_items(axis):
        status, _ = _record_classification(entry["items"][item], True, require_link=(axis == "Integração"))
        counts[status] += 1
    return counts


def _percent_1dp(numerator, denominator):
    """Percentual arredondado a 1 casa pelo critério decimal HALF_UP."""
    if not denominator:
        return 0.0
    exact = Decimal(int(numerator)) * Decimal(100) / Decimal(int(denominator))
    return float(exact.quantize(Decimal("0.1"), rounding=ROUND_HALF_UP))


def _breakdown_metrics(axis, counts):
    total = len(axis_items(axis))
    yes = counts["yes"]
    evaluated = yes + counts["no"]
    percentage = _percent_1dp(yes, total)
    return percentage, yes, total, evaluated


def calc_axis(axis):
    """Estatísticas do rascunho; nunca utilizadas no diagnóstico final."""
    return _breakdown_metrics(axis, _draft_breakdown(axis))


def _missing_record_fields(record, require_link=False):
    """Informa os nomes dos campos visíveis incompletos, preservando o código 0."""
    status = record.get("status", STATUS_UNASSESSED)
    if status == STATUS_UNASSESSED:
        return ["Codificação documental: selecione presença (1) ou ausência (0)"]
    if status not in (STATUS_POSITIVE, STATUS_NEGATIVE):
        return ["Codificação documental: seleção inválida"]
    document = str(record.get("document") or "").strip()
    missing = []
    if len(document) < 5 or _is_ui_error_text(document):
        missing.append("Documento / relatório-fonte" if status == STATUS_POSITIVE
                       else "Documento / relatório examinado para registrar 0")
    if status == STATUS_POSITIVE:
        page = str(record.get("page") or "").strip()
        quote = str(record.get("quote") or "").strip()
        if len(page) < 2 or _is_ui_error_text(page):
            missing.append("Página, nota ou localização verificável")
        if len(quote) < 12 or _is_ui_error_text(quote):
            missing.append("Trecho ORIGINAL do relatório que fundamenta o código 1")
        if require_link and len(str(record.get("link_reason") or "").strip()) < 12:
            missing.append("Justificativa da conexão explícita entre os eixos")
    return missing


def _axis_errors(axis):
    """Relação detalhada de campos, por elemento, para o aviso pré-envio."""
    errors = []
    if not _context_ready():
        identity = st.session_state.get("case_identity", {})
        if not str(identity.get("company") or "").strip():
            errors.append("Unidade de análise → Empresa analisada")
        if str(identity.get("year") or "").strip() in ("", "Selecione", "None"):
            errors.append("Unidade de análise → Exercício")
        if not str(identity.get("issuer") or "").strip():
            errors.append("Unidade de análise → Pessoa jurídica emissora / nível de consolidação")
    for item in axis_items(axis):
        record = evidence_record(axis, item)
        for field_name in _missing_record_fields(record, require_link=(axis == "Integração")):
            errors.append(f"{item} → {field_name}")
    return errors


def _submit_axis(axis):
    _sync_axis_draft(axis)
    errors = _axis_errors(axis)
    if errors:
        return errors
    st.session_state.axis_submissions[axis] = {
        "context": _case_identity(),
        "items": {item: _canonical_record(st.session_state.draft_records[axis][item])
                  for item in axis_items(axis)},
    }
    return []


def _all_axes_submitted():
    return all(_submission_for(axis) is not None for axis in AXIS_SEQUENCE)

def _all_groups_submitted():
    return all(_submission_for(group) is not None for group in SUBMISSION_SEQUENCE)


def evidence_controls(axis, item):
    token = response_key(axis, item)
    rule = EVIDENCE_RULES.get(item, {})
    current_status = evidence_record(axis, item)["status"]
    with st.expander(item, expanded=current_status == STATUS_POSITIVE):
        st.caption("**O que representa:** " + _brief_element_definition(item))
        st.caption("Critério para codificação 1: " + rule.get("criterion", "Evidência contextualizada e explícita."))
        if rule.get("exclude"):
            st.caption("Não considerar: " + rule["exclude"])
        status = st.selectbox("Codificação documental", STATUS_OPTIONS,
                              key="status_" + token, on_change=mark_axis_dirty, args=(axis, item))
        if status == STATUS_POSITIVE:
            st.text_input("Documento / relatório-fonte", key="document_" + token,
                          placeholder="Ex.: Demonstrações financeiras consolidadas de 2022",
                          on_change=mark_axis_dirty, args=(axis, item))
            st.text_input("Página, nota ou localização verificável", key="page_ref_" + token,
                          placeholder="Ex.: Nota 16, p. 70", on_change=mark_axis_dirty, args=(axis, item))
            st.text_area("Trecho ORIGINAL do relatório que fundamenta o código 1",
                         key="quote_" + token, height=95,
                         placeholder="Transcreva somente o trecho do documento empresarial.",
                         on_change=mark_axis_dirty, args=(axis, item))
            if axis == "Integração":
                st.text_area("Justificativa da relação explícita entre as dimensões",
                             key="reason_" + token, height=85,
                             placeholder="Indique quais elementos são relacionados e como o trecho demonstra a conexão.",
                             on_change=mark_axis_dirty, args=(axis, item))
        elif status == STATUS_NEGATIVE:
            st.text_input("Documento / relatório examinado para registrar 0", key="document_" + token,
                          placeholder="Ex.: XP Inc. — Form 20-F de 2022",
                          on_change=mark_axis_dirty, args=(axis, item))
            st.caption("O código 0 indica que o elemento não foi localizado no documento examinado; não significa inexistência do recurso.")
        classification, reason = _record_classification(evidence_record(axis, item), _context_ready(), require_link=(axis == "Integração"))
        if classification == "yes":
            st.success("Código 1 documentado. Será incorporado após o envio deste eixo.")
        elif classification == "no":
            st.caption("Código 0 documentado: ausência no corpus examinado, não inexistência do recurso.")
        elif status != STATUS_UNASSESSED:
            if not _context_ready():
                st.caption("Preencha a unidade de análise no início desta página para validar a resposta.")
            else:
                st.warning(reason)


def _evidence_export(submitted_only=False):
    """CSV com estado explícito dos códigos; nenhuma pendência vira zero."""
    records = []
    for axis in SUBMISSION_SEQUENCE:
        entry = _submission_for(axis)
        for item in axis_items(axis):
            rec = (entry["items"][item] if submitted_only and entry
                   else _canonical_record(evidence_record(axis, item)))
            status, _ = _record_classification(rec, _context_ready(), require_link=(axis == "Integração"))
            if status == "yes": code = 1
            elif status == "no": code = 0
            elif status == "unanswered": code = "não avaliado"
            else: code = "pendente de evidência"
            if submitted_only and entry is None:
                code = "grupo não enviado"
            records.append({
                "empresa": _case_identity()[0],
                "ano": _case_identity()[1],
                "emissora_escopo": _case_identity()[2],
                "padrao": _case_identity()[3],
                "eixo": axis, "variavel": item,
                "eixo_enviado": "sim" if entry else "não",
                "status_selecionado": rec["status"],
                "codigo": code,
                "documento": rec["document"], "pagina": rec["page"],
                "trecho_original": rec["quote"], "delimitacao_busca": rec["scope"],
                "justificativa_conexao": rec["link_reason"],
            })
    frame = pd.DataFrame(records)
    # CSV seguro para abrir no Excel: texto não deve executar fórmulas.
    for name in frame.columns:
        frame[name] = frame[name].map(
            lambda x: "'" + x if isinstance(x, str) and x.startswith(("=", "+", "-", "@")) else x
        )
    return frame.to_csv(index=False, sep=";", encoding="utf-8-sig").encode("utf-8-sig")


def _restore_evidence_csv(upload):
    """Recupera um rascunho exportado, sem trocar silenciosamente a unidade de análise.

    Os valores são aplicados antes da renderização dos controles dos eixos.
    """
    content = upload.getvalue()
    if not content or len(content) > 5_000_000:
        raise ValueError("O CSV está vazio ou excede 5 MB.")
    data = pd.read_csv(io.BytesIO(content), sep=";", encoding="utf-8-sig",
                       dtype=str, keep_default_na=False)
    must_have = {"empresa", "ano", "emissora_escopo", "eixo", "variavel", "codigo",
                 "documento", "pagina", "trecho_original", "delimitacao_busca"}
    if not must_have.issubset(data.columns):
        raise ValueError("O arquivo não contém as colunas do CSV exportado pelo framework.")
    expected = {(axis, item) for axis in SUBMISSION_SEQUENCE for item in axis_items(axis)}
    legacy = {(axis, item) for axis in AXIS_SEQUENCE for item in axis_items(axis)}
    actual = list(zip(data["eixo"].tolist(), data["variavel"].tolist()))
    if len(actual) != len(set(actual)) or set(actual) not in (expected, legacy):
        raise ValueError("O CSV deve conter 48 variáveis (ou 42 no formato legado, para recuperação de rascunhos).")
    company, year, issuer, standard = _case_identity()
    def unique(name):
        values = {str(v).strip() for v in data[name].tolist()}
        if len(values) != 1:
            raise ValueError(f"O CSV contém mais de uma unidade no campo {name}.")
        return next(iter(values))
    file_company, file_year, file_issuer = [unique(k) for k in ("empresa", "ano", "emissora_escopo")]
    if not _context_ready() or (company, year, issuer) != (file_company, file_year, file_issuer):
        raise ValueError("Informe a MESMA empresa, exercício e emissora do CSV antes de restaurá-lo (no topo do eixo ou na barra lateral).")
    if "padrao" in data.columns and unique("padrao") != standard:
        raise ValueError("Selecione o mesmo padrão contábil informado no arquivo antes de restaurar.")
    reset_case_assessment()
    for _index, row in data.iterrows():
        axis, item = row["eixo"], row["variavel"]
        token = response_key(axis, item)
        status = row.get("status_selecionado", "")
        if status not in STATUS_OPTIONS:
            code = str(row["codigo"]).strip()
            status = STATUS_POSITIVE if code == "1" else (
                STATUS_NEGATIVE if code == "0" else STATUS_UNASSESSED)
        restored_record = {
            "status": status,
            "document": str(row.get("documento", "")),
            "page": str(row.get("pagina", "")),
            "quote": str(row.get("trecho_original", "")),
            "scope": str(row.get("delimitacao_busca", "")),
            "link_reason": str(row.get("justificativa_conexao", "")),
        }
        st.session_state.draft_records.setdefault(axis, {})[item] = _canonical_record(restored_record)
    # Recupera os eixos que estavam enviados, se continuam documentalmente válidos.
    if "eixo_enviado" in data.columns:
        for axis in SUBMISSION_SEQUENCE:
            part = data[data["eixo"] == axis]
            if len(part) == len(axis_items(axis)) and all(
                    norm(v) == "sim" for v in part["eixo_enviado"].tolist()):
                _submit_axis(axis)
    return len(data)


