def vg_matrix():
    A = VG["axis"]
    R = VG["rsl_axis"]
    def cell(axis_tag, big, text, src, gap=False):
        return (f'<div class="vg-mc{" gap" if gap else ""}"><span class="tag">{axis_tag}</span>'
                f'<span class="big">{big}</span>{text}<span class="src"><b>Fonte:</b> {src}</span></div>')
    rows = [
        (f'<div class="vg-mr"><h4>Literatura (RSL)</h4>Os {VG["rsl_funil"][-1][1]} artigos incluídos'
         '<div class="rule"><b>Regra de evidência</b>Conta o artigo cuja abordagem de mensuração, registrada na leitura integral, inclui o eixo.</div></div>',
         [cell("Contábil", f'{R["Contábil"]} artigos', 'A RSL fundamenta os elementos contábeis. A análise normativa posterior especifica os requisitos de reconhecimento, mensuração, vida útil, recuperabilidade e divulgação.', 'RSL, abas Full-Text Review e OUTRAS ANALISES'),
          cell("Financeiro", f'{R["Financeiro"]} artigos', 'Métricas complementares aproximam valor econômico: EVA, VAIC, Tobin\'s Q, Market-to-Book, ROA, ROIC, EBITDA. Não são universalmente divulgadas.', 'RSL, abas INCLUÍDO (Full-Text) e OUTRAS ANALISES'),
          cell("Estratégico", f'{R["Estratégico"]} artigos', 'Capital intelectual, tecnologia e capacidades como fontes de valor. Alta heterogeneidade conceitual.', 'RSL, abas INCLUÍDO (Full-Text) e OUTRAS ANALISES')]),
        ('<div class="vg-mr"><h4>Normas</h4>CPC e IFRS/IAS'
         '<div class="rule"><b>Regra de evidência</b>Requisito com norma e parágrafo citados; a norma delimita o que é reconhecido, não prova a existência do recurso.</div></div>',
         [cell("Contábil", 'CPC 04 / IAS 38', 'Definição, identificabilidade, controle e benefícios prováveis (itens 8, 12, 13–16, 21); amortização, vida útil e divulgação (88–110, 118–128). CPC 00 e CPC 15 / IFRS 3 completam o núcleo.', 'Extração Normativa, aba Extracao'),
          cell("Financeiro", 'CPC 46 · CPC 01', 'CPC 46/IFRS 13 e CPC 01/IAS 36 fornecem contexto de avaliação contábil, mas não criam indicadores financeiros pontuados: os nove elementos financeiros permanecem aqueles definidos pela RSL e codificados na matriz EIXOS.', 'Extração Normativa, abas Extracao e HIERARQUIA NORMATIVA'),
          cell("Estratégico", 'Limite do reconhecimento', 'As normas delimitam o reconhecimento de recursos e podem explicar diferenças entre informação contábil e estratégica. Não originam nem validam automaticamente os 16 elementos estratégicos, cuja base é a RSL.', 'Extração Normativa, aba Extracao', gap=True)]),
        (f'<div class="vg-mr"><h4>Empresas</h4>{VG["n_firms"]} fintechs · exercícios da matriz'
         '<div class="rule"><b>Regra de evidência</b>Vale 1 só com evidência explícita no documento; sem ela vale 0. Não se infere nem se calcula valor ausente.</div></div>',
         [cell("Contábil", _pc(_vg_pct("Contábil")), f'Goodwill: {VG["var_count"]["Goodwill / Ágio"]}; software: {VG["var_count"]["Software"]}; amortização: {VG["var_count"]["Amortização"]}; impairment: {VG["var_count"]["Impairment"]}; vida útil: {VG["var_count"]["Vida útil"]}; valor justo: {VG["var_count"]["Valor justo"]}.', 'Fintechs, abas EIXOS e RESUMO EIXOS'),
          cell("Financeiro", _pc(_vg_pct("Financeiro")), f'Valor contábil dos intangíveis: {VG["var_count"]["Valor contábil dos intangíveis"]}/{VG["obs"]} observações; as demais oito variáveis financeiras somam {VG["fin_sem_vc"]["ev"]}/{VG["fin_sem_vc"]["tot"]} registros. Métricas não são estimadas quando ausentes.', 'Fintechs, aba EIXOS', gap=True),
          cell("Estratégico", _pc(_vg_pct("Estratégico")), f'Patentes: {VG["var_count"]["Patentes"]}; clientes/relacionamento: {VG["var_count"]["Clientes / relacionamento"]}; capacitação: {VG["var_count"]["Capacitação / treinamento"]}; participação de mercado: {VG["var_count"]["Market share"]}; marca: {VG["var_count"]["Marca e reputação corporativa"]}.', 'Fintechs, aba EIXOS', gap=True)]),
    ]
    body = '<div class="vg-mh blank"></div><div class="vg-mh c">Contábil</div><div class="vg-mh f">Financeiro</div><div class="vg-mh e">Estratégico</div>'
    for head, cells in rows:
        body += head + "".join(cells)
    return _h(f'''
<section class="vg-section">
  <div class="vg-head"><span class="eyebrow">Matriz de triangulação 3 × 3</span>
  <h2>Literatura, normas e empresas sobre os três eixos.</h2>
  <p>A contribuição está em comparar as linhas: o que a literatura propõe, o que as normas reconhecem e o que as empresas divulgam de fato. Cada célula indica a fonte e segue a regra de evidência da sua linha.</p></div>
  <div class="vg-matrix">{body}</div>
  <div class="vg-cap">Células em tom claro sinalizam lacuna: o eixo é relevante na literatura, mas pouco ou nada aparece na divulgação das empresas. Artigos podem pertencer a mais de um eixo; Alguns estudos podem ter abordagem classificada como outra (data-driven, teórica ou híbrida).</div>
</section>''')

def vg_triangulation():
    pc, pf, pe = _vg_pct("Contábil"), _vg_pct("Financeiro"), _vg_pct("Estratégico")
    rows = "".join(
        f'<tr><td>{n}</td><td class="n">{_pc(c)}</td><td class="n">{_pc(f)}</td><td class="n">{_pc(e)}</td><td class="n">{i}</td></tr>'
        for n, c, f, e, i in VG["empresas"])
    return _h(f'''
<section class="vg-section">
  <div class="vg-head"><span class="eyebrow">Triangulação</span>
  <h2>Onde as três fontes convergem e onde divergem.</h2>
  <p>A presença codificada é de {_pc(pc)} no eixo contábil, {_pc(pf)} no financeiro e {_pc(pe)} no estratégico (células codificadas como 1 sobre o total possível, em {VG["obs"]} observações empresa-ano).</p></div>
  <div class="vg-tri">
    <article class="vg-tcard c"><div class="th"><span>Contábil</span><span class="vg-badge">Convergência</span></div><div class="tb">
      <b>{_pc(pc)}</b> de presença
      <div class="vg-bar"><i style="width:{pc:.1f}%"></i></div>
      <ul><li>A literatura ({VG["rsl_axis"]["Contábil"]} artigos) e as normas tratam reconhecimento e mensuração como núcleo.</li>
      <li>As empresas divulgam sobretudo o que as normas exigem: goodwill, software, amortização e impairment.</li>
      <li>Vida útil ({VG["var_count"]["Vida útil"]}) e valor justo ({VG["var_count"]["Valor justo"]}) têm contagens específicas na matriz.</li></ul></div></article>
    <article class="vg-tcard f"><div class="th"><span>Financeiro</span><span class="vg-badge">Divergência</span></div><div class="tb">
      <b>{_pc(pf)}</b> de presença
      <div class="vg-bar"><i style="width:{pf:.1f}%"></i></div>
      <ul><li>A RSL fundamenta os indicadores financeiros; valor justo e valor recuperável são referências contábeis condicionadas às normas, não substitutos dos nove elementos financeiros efetivamente pontuados.</li>
      <li>O valor contábil soma {VG["var_count"]["Valor contábil dos intangíveis"]} presenças e as demais métricas financeiras {VG["fin_sem_vc"]["ev"]}, considerando exclusivamente o corpus analisado.</li>
      <li>Ausência documental não é ausência econômica.</li></ul></div></article>
    <article class="vg-tcard e"><div class="th"><span>Estratégico</span><span class="vg-badge">Divergência parcial</span></div><div class="tb">
      <b>{_pc(pe)}</b> de presença
      <div class="vg-bar"><i style="width:{pe:.1f}%"></i></div>
      <ul><li>A literatura ({VG["rsl_axis"]["Estratégico"]} artigos) trata capital intelectual e tecnologia como fonte de valor.</li>
      <li>O reconhecimento desses recursos depende de requisitos específicos; sua menção estratégica não os transforma em ativos contabilizados.</li>
      <li>As taxas por empresa dependem da cobertura documental codificada e do conjunto de arquivos examinado.</li></ul></div></article>
  </div>
  <div class="vg-callout"><b>Leitura central:</b> as frequências descrevem somente a matriz documental da dissertação, não toda a informação disponível das empresas. A interpretação considera a cobertura dos relatórios e distingue valor contábil de métricas econômicas complementares.</div>
  <table class="vg-table"><thead><tr><th>Empresa</th><th>Contábil</th><th>Financeiro</th><th>Estratégico</th><th>Conexões C↔E</th></tr></thead><tbody>{rows}</tbody></table>
  <div class="vg-cap">Percentual de variáveis com evidência explícita em cada eixo, nos exercícios disponíveis de cada empresa. Esses percentuais são orientados pelos dados empíricos da dissertação, a partir da matriz EIXOS da amostra, com 42 variáveis operacionais (17 contábeis, 9 financeiras e 16 estratégicas) distribuídas em 30 observações empresa-ano. Os percentuais são agregados por eixo e dependem do número de variáveis; a contribuição do valor contábil e das demais métricas deve ser conferida na matriz carregada. Fonte: matriz EIXOS carregada; percentuais recalculados automaticamente.</div>
</section>''')

