def supplementary_group_page(group):
    if group == "Identificação":
        heading = "Identificação do fenômeno"
        subtitle = ("Dois registros que permitem localizar o ativo intangível e a tecnologia/inovação "
                    "documentados na unidade de análise. Não se confundem com os 42 elementos dos eixos.")
        next_page = AXIS_PAGES["Contábil"]
    else:
        heading = "Integração dos eixos"
        subtitle = ("Quatro verificações de articulação explícita entre as dimensões, "
                    "incluindo a mensuração integrada dos três eixos.")
        next_page = "05 · Diagnóstico"
    st.markdown(f"""<div class="page-hero" style="background:#142B45;">
       <div class="num">DICIONÁRIO OPERACIONAL · 48 VARIÁVEIS</div>
       <h1>{heading}.</h1><p>{subtitle}</p></div>""", unsafe_allow_html=True)
    _render_case_identity_editor()
    st.caption(f"Etapa com {len(axis_items(group))} variável(is). Código 1 requer documento, "
               "localização e trecho original; código 0 requer identificação do documento examinado. "
               "As conexões positivas também requerem justificativa explícita.")
    _hydrate_axis_widgets(group)
    for item in axis_items(group):
        evidence_controls(group, item)
    counts = _draft_breakdown(group)
    yes = counts["yes"]
    assessed = yes + counts["no"]
    st.divider()
    c1, c2 = st.columns(2)
    c1.metric("Presenças documentadas", f"{yes}/{len(axis_items(group))}")
    c2.metric("Registros válidos", f"{assessed}/{len(axis_items(group))}")
    errors = _axis_errors(group)
    if _submission_for(group):
        st.success("Etapa enviada e validada. Qualquer alteração exigirá novo envio.")
    if errors:
        with st.expander(f"Conferir {len(errors)} pendência(s)", expanded=False):
            for issue in errors:
                st.write("• " + issue)
    st.download_button("Salvar rascunho completo (CSV)", data=_evidence_export(),
                       file_name="framework_rascunho_48_variaveis.csv", mime="text/csv",
                       key="draft_extra_" + norm(group))
    if st.button("Enviar " + heading.lower() + " e continuar", type="primary",
                 use_container_width=True, key="submit_extra_" + norm(group)):
        problems = _submit_axis(group)
        if problems:
            st.error(f"Existem {len(problems)} campos a completar.")
            for issue in problems:
                st.write("• " + issue)
        else:
            _navigate_to(next_page)


